/**
 * Placement registry — architect spec AD-10.
 *
 * Marketing adds a placement by editing `src/data/placements.json` and
 * regenerating its QR code; adding one already implies a redeploy (a new QR
 * must be printed), so data-file + rebuild is the correct workflow.
 *
 * The *active* keys are what the boot script embeds for `placementValid`, so
 * `listActivePlacements()` is the single source of truth for validity.
 */

import registryJson from "@/data/placements.json";

export interface PlacementEntry {
  label: string;
  active: boolean;
}

const REGISTRY = registryJson as Record<string, PlacementEntry>;

/** Is this code a known, active placement? (FR-1, FR-4, C-14) */
export function isKnownPlacement(code: string): boolean {
  return (
    Object.prototype.hasOwnProperty.call(REGISTRY, code) &&
    REGISTRY[code]!.active === true
  );
}

export function getPlacementEntry(code: string): PlacementEntry | null {
  return REGISTRY[code] ?? null;
}

export function listActivePlacements(): { code: string; label: string }[] {
  return Object.entries(REGISTRY)
    .filter(([, entry]) => entry.active)
    .map(([code, entry]) => ({ code, label: entry.label }));
}

/**
 * Resolve an incoming path segment to the value stored in attribution/analytics.
 * Unknown or inactive codes collapse to "unknown" (FR-4 acceptance criteria,
 * FR-23 `placement_code`). The raw path is still captured on the `qr_scan`
 * event as `landing_path`, so nothing is lost for diagnostics.
 */
export function resolvePlacement(code: string): {
  placement: string;
  valid: boolean;
} {
  return isKnownPlacement(code)
    ? { placement: code, valid: true }
    : { placement: "unknown", valid: false };
}
