/**
 * Typed runtime config — architect spec §7.4.
 *
 * This module is imported by client components, so it must stay dependency-free:
 * plain constants only, no zod. `import type` is erased at compile time, so the
 * *type* of the validated config is available without pulling the validator
 * into the browser bundle.
 *
 * Values are validated by `validateEnv()` — called from `next.config.ts` (the
 * earliest possible gate) and from the root layout during prerender (AD-9).
 * The two layers read the same `process.env`, so what ships is what was checked.
 *
 * `process.env.NEXT_PUBLIC_*` is written out key-by-key on purpose: Next.js
 * inlines direct member expressions only, not whole objects.
 */

import type { Env } from "./schema";

const raw = {
  NEXT_PUBLIC_WHATSAPP_NUMBER: process.env.NEXT_PUBLIC_WHATSAPP_NUMBER ?? "",
  NEXT_PUBLIC_SITE_URL: process.env.NEXT_PUBLIC_SITE_URL ?? "",
  NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS:
    process.env.NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS ?? "30",
  NEXT_PUBLIC_DISCOUNT_PERCENT: process.env.NEXT_PUBLIC_DISCOUNT_PERCENT ?? "5",
  NEXT_PUBLIC_DISCOUNT_PREFIX: process.env.NEXT_PUBLIC_DISCOUNT_PREFIX ?? "QR5",
  NEXT_PUBLIC_DISCOUNT_RAND_LEN:
    process.env.NEXT_PUBLIC_DISCOUNT_RAND_LEN ?? "6",
  NEXT_PUBLIC_DISCOUNT_EXPIRY:
    process.env.NEXT_PUBLIC_DISCOUNT_EXPIRY ?? "2026-12-31",
  NEXT_PUBLIC_FALLBACK_TIMEOUT_MS:
    process.env.NEXT_PUBLIC_FALLBACK_TIMEOUT_MS ?? "1600",
  NEXT_PUBLIC_ANALYTICS_PROVIDER:
    process.env.NEXT_PUBLIC_ANALYTICS_PROVIDER ?? "console",
} as const;

/**
 * Coerced to the same shape `validateEnv()` produces, so client and server
 * agree on types. The build gate guarantees these are the validated strings.
 */
export const config = {
  NEXT_PUBLIC_WHATSAPP_NUMBER: raw.NEXT_PUBLIC_WHATSAPP_NUMBER,
  NEXT_PUBLIC_SITE_URL: raw.NEXT_PUBLIC_SITE_URL,
  NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS: Number(
    raw.NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS,
  ),
  NEXT_PUBLIC_DISCOUNT_PERCENT: Number(raw.NEXT_PUBLIC_DISCOUNT_PERCENT),
  NEXT_PUBLIC_DISCOUNT_PREFIX: raw.NEXT_PUBLIC_DISCOUNT_PREFIX,
  NEXT_PUBLIC_DISCOUNT_RAND_LEN: Number(raw.NEXT_PUBLIC_DISCOUNT_RAND_LEN),
  NEXT_PUBLIC_DISCOUNT_EXPIRY: raw.NEXT_PUBLIC_DISCOUNT_EXPIRY,
  NEXT_PUBLIC_FALLBACK_TIMEOUT_MS: Number(raw.NEXT_PUBLIC_FALLBACK_TIMEOUT_MS),
  NEXT_PUBLIC_ANALYTICS_PROVIDER: raw.NEXT_PUBLIC_ANALYTICS_PROVIDER as Env["NEXT_PUBLIC_ANALYTICS_PROVIDER"],
} satisfies Env;

/** Convenience accessors so call sites stay readable. */
export const whatsappNumber = config.NEXT_PUBLIC_WHATSAPP_NUMBER;
export const attributionWindowDays = config.NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS;
export const discountPercent = config.NEXT_PUBLIC_DISCOUNT_PERCENT;
