/**
 * Storage abstraction — architect spec §7.2.
 *
 * All cookie/sessionStorage access goes through this interface so that:
 *  - `src/lib` stays free of DOM globals and is unit-testable in a plain Node
 *    environment (architect spec §6, plan Phase 1);
 *  - a future consent gate (C-15, open question Q1) is a single seam rather
 *    than a refactor across the codebase.
 */

export interface StorageAdapter {
  getCookie(name: string): string | null;
  setCookie(name: string, value: string, maxAgeSec: number): void;
  removeCookie(name: string): void;
  sessionGet(key: string): string | null;
  sessionSet(key: string, value: string): void;
  sessionRemove(key: string): void;
}

/**
 * In-memory adapter for unit tests.
 *
 * Note: `maxAgeSec` is deliberately not simulated — tests assert it via
 * `vi.spyOn(storage, "setCookie")` rather than by running a clock.
 */
export function createMemoryStorage(
  seed?: { cookies?: Record<string, string>; session?: Record<string, string> },
): StorageAdapter {
  const cookies = new Map<string, string>(Object.entries(seed?.cookies ?? {}));
  const session = new Map<string, string>(Object.entries(seed?.session ?? {}));
  return {
    getCookie: (name) => cookies.get(name) ?? null,
    setCookie: (name, value) => {
      cookies.set(name, value);
    },
    removeCookie: (name) => {
      cookies.delete(name);
    },
    sessionGet: (key) => session.get(key) ?? null,
    sessionSet: (key, value) => {
      session.set(key, value);
    },
    sessionRemove: (key) => {
      session.delete(key);
    },
  };
}

/** Every access is guarded: storage can be unavailable in private-browsing modes. */
export const browserStorage: StorageAdapter = {
  getCookie(name) {
    if (typeof document === "undefined") return null;
    try {
      const parts = document.cookie ? document.cookie.split("; ") : [];
      for (const part of parts) {
        const eq = part.indexOf("=");
        if (eq <= 0) continue;
        if (decodeURIComponent(part.slice(0, eq)) !== name) continue;
        try {
          return decodeURIComponent(part.slice(eq + 1));
        } catch {
          return part.slice(eq + 1);
        }
      }
    } catch {
      /* fall through */
    }
    return null;
  },

  setCookie(name, value, maxAgeSec) {
    if (typeof document === "undefined") return;
    try {
      const secure =
        typeof location !== "undefined" && location.protocol === "https:"
          ? "; Secure"
          : "";
      document.cookie = `${name}=${encodeURIComponent(value)};path=/;max-age=${maxAgeSec};SameSite=Lax${secure}`;
    } catch {
      /* no-op — attribution degrades, the funnel must not break */
    }
  },

  removeCookie(name) {
    if (typeof document === "undefined") return;
    try {
      document.cookie = `${name}=;path=/;max-age=0;SameSite=Lax`;
    } catch {
      /* no-op */
    }
  },

  sessionGet(key) {
    if (typeof sessionStorage === "undefined") return null;
    try {
      return sessionStorage.getItem(key);
    } catch {
      return null;
    }
  },

  sessionSet(key, value) {
    if (typeof sessionStorage === "undefined") return;
    try {
      sessionStorage.setItem(key, value);
    } catch {
      /* no-op */
    }
  },

  sessionRemove(key) {
    if (typeof sessionStorage === "undefined") return;
    try {
      sessionStorage.removeItem(key);
    } catch {
      /* no-op */
    }
  },
};
