"use client";

import { useEffect } from "react";

import { getAnalytics } from "@/analytics";
import {
  ensureAttribution,
  getAppAttribution,
  getAppSession,
  persistDiscountCode,
} from "@/analytics/context";
import { reportWebVitals } from "@/analytics/vitals";
import { config } from "@/config";
import { parseQrContext } from "@/lib/attribution";
import { ensureDiscountCode } from "@/lib/discount";

/**
 * The first client pass — mounted once at the top of the root layout, before
 * any page content. It does four things, in this order:
 *
 *  1. **Ensure attribution** (FR-2/FR-4) — idempotent; the boot script has
 *     usually already done this, but the app must not depend on it.
 *  2. **Mint the discount code** (FR-16) — once per QR session, then notifies
 *     the store so `DiscountBanner` and `Handoff` pick it up through
 *     `useSyncExternalStore` instead of `setState`-in-effect.
 *  3. **Emit `qr_scan` / `page_view`** (FR-22). `qr_scan` fires ONLY when the
 *     request URL itself carried QR context and at most once per session
 *     (C-3) — a returning visitor landing on `/` with a valid cookie is tagged
 *     `route=qr` but must not inflate the G1 denominator (C-2).
 *  4. **Report web vitals** (architect §8) so a G1 miss caused by performance
 *     rather than copy can be diagnosed.
 */
export function ClientBootstrap() {
  useEffect(() => {
    const attr = ensureAttribution(window.location);

    const minted = ensureDiscountCode({
      read: getAppAttribution().read,
      setCode: persistDiscountCode,
      prefix: config.NEXT_PUBLIC_DISCOUNT_PREFIX,
      length: config.NEXT_PUBLIC_DISCOUNT_RAND_LEN,
    });
    if (minted.created && minted.code) {
      getAnalytics().track("discount_code_generated", {
        discount_code: minted.code,
      });
    }

    getAnalytics().track("page_view", { path: window.location.pathname });

    const { hasQrContext } = parseQrContext(window.location);
    if (hasQrContext && getAppSession().claimQrScan()) {
      getAnalytics().track("qr_scan", {
        landing_path: window.location.pathname,
        placement_valid:
          attr?.placementValid ??
          getAppAttribution().read()?.placementValid ??
          false,
      });
    }

    reportWebVitals();
  }, []);

  return null;
}
